import json
import unittest

DIAG = "/private/var/folders/mx/w46p9btx1t17wv9tbsq885qw0000gn/T/richos-owned-wake-native-84qmwqjb/workspace/diagnosis.json"
ALLOWED = {"obsolete_assertion", "implementation_defect"}


class DiagnosisShape(unittest.TestCase):
    def setUp(self):
        with open(DIAG) as fh:
            self.d = json.load(fh)  # fails loudly if not valid JSON

    def test_parses_to_object(self):
        self.assertIsInstance(self.d, dict)

    def test_native_is_allowed_top_level_string(self):
        self.assertIn("native", self.d)
        self.assertIsInstance(self.d["native"], str)
        self.assertIn(self.d["native"], ALLOWED)

    def test_external_is_allowed_top_level_string(self):
        self.assertIn("external", self.d)
        self.assertIsInstance(self.d["external"], str)
        self.assertIn(self.d["external"], ALLOWED)

    def test_evidence_is_separate_object(self):
        self.assertIn("evidence", self.d)
        self.assertIsInstance(self.d["evidence"], dict)

    def test_classifications_match_requirements(self):
        # native: code already returned platform-pending (correct); test asserted
        # the superseded "verified" -> the check was obsolete.
        self.assertEqual(self.d["native"], "obsolete_assertion")
        # external: test asserted verified (correct); code returned "bound" -> code was broken.
        self.assertEqual(self.d["external"], "implementation_defect")


if __name__ == "__main__":
    unittest.main()
